/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=deal, operation=update
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Update an activity */
export type PipedriveV2DealUpdateParams = {
  resource: 'deal';
  operation: 'update';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal to update
 * @default 0
 */
    dealId?: number | Expression<number>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Currency of the deal. Accepts a 3-character currency code. Like EUR, USD, ...
     * @default USD
     */
    currency?: string | Expression<string> | PlaceholderValue;
    /** The expected close date of the deal in YYYY-MM-DD format
     */
    expected_close_date?: string | Expression<string>;
    /** Choose from the list, or specify IDs using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
     * @loadOptionsMethod getDealLabels
     * @default []
     */
    label_ids?: string[];
    /** Reason why the deal was lost
     */
    lost_reason?: string | Expression<string> | PlaceholderValue;
    /** ID of the organization this deal will be associated with. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getOrganizationIds
     */
    org_id?: string | Expression<string>;
    /** ID of the person this deal will be associated with
     * @default 0
     */
    person_id?: number | Expression<number>;
    /** Deal success probability percentage
     * @default 0
     */
    probability?: number | Expression<number>;
    /** ID of the stage this deal will be placed in a pipeline. If omitted, the deal will be placed in the first stage of the default pipeline. (PIPELINE &gt; STAGE). Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getStageIds
     */
    stage_id?: string | Expression<string>;
    /** The status of the deal. If not provided it will automatically be set to "open".
     * @default open
     */
    status?: 'open' | 'won' | 'lost' | 'deleted' | Expression<string>;
    /** The title of the deal
     */
    title?: string | Expression<string> | PlaceholderValue;
    /** ID of the active user whom the deal will be assigned to. If omitted, the deal will be assigned to the authorized user. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getUserIds
     */
    user_id?: string | Expression<string>;
    /** Value of the deal. If not set it will automatically be set to 0.
     * @default 0
     */
    value?: number | Expression<number>;
    /** Visibility of the item. If omitted, visibility will be set to the default visibility setting of this item type for the authorized user.
     * @default 3
     */
    visible_to?: '1' | '3' | Expression<string>;
    /** Custom Fields
     * @default {}
     */
    customFields?: {
        /** Property
     */
    property?: Array<{
      /** The name or key of the custom field as it appears in Pipedrive
       */
      name?: string | Expression<string> | PlaceholderValue;
      /** The value to set for the custom field
       */
      value?: string | Expression<string> | PlaceholderValue;
    }>;
  };
  };
/**
 * Whether to provide raw Pipedrive field keys and option IDs instead of human-readable names
 * @default false
 */
    rawCustomFieldKeys?: boolean | Expression<boolean>;
};

export type PipedriveV2DealUpdateOutput = {
  active?: boolean;
  activities_count?: number;
  add_time?: string;
  cc_email?: string;
  creator_user_id?: {
    active_flag?: boolean;
    email?: string;
    has_pic?: number;
    id?: number;
    name?: string;
    value?: number;
  };
  currency?: string;
  deleted?: boolean;
  done_activities_count?: number;
  email_messages_count?: number;
  files_count?: number;
  followers_count?: number;
  formatted_value?: string;
  formatted_weighted_value?: string;
  id?: number;
  notes_count?: number;
  org_hidden?: boolean;
  owner_name?: string;
  participants_count?: number;
  person_hidden?: boolean;
  person_id?: {
    active_flag?: boolean;
    email?: Array<{
      label?: string;
      primary?: boolean;
      value?: string;
    }>;
    name?: string;
    owner_id?: number;
    phone?: Array<{
      label?: string;
      primary?: boolean;
      value?: string;
    }>;
    value?: number;
  };
  pipeline_id?: number;
  products_count?: number;
  stage_id?: number;
  stage_order_nr?: number;
  status?: string;
  title?: string;
  undone_activities_count?: number;
  update_time?: string;
  user_id?: {
    active_flag?: boolean;
    email?: string;
    has_pic?: number;
    id?: number;
    name?: string;
    value?: number;
  };
  visible_to?: string;
  weighted_value_currency?: string;
};

export type PipedriveV2DealUpdateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2DealUpdateParams>;
  output?: Items<PipedriveV2DealUpdateOutput>;
};